export const ui: Record<Lang, Dict> = { en, nl, fr };
export const t = (lang: Lang) => ui[lang];
export const fmt = (s: string, v: Record<string, string | number>) => s.replace(/\{(\w+)\}/g, (_, k) => String(v[k] ?? ''));
/** Localised path: lp('nl', '/solutions/') -> '/nl/solutions/' */
export const lp = (lang: Lang, path: string) => (lang === 'en' ? path : `/${lang}${path}`);
/** Strip a language prefix from a pathname. */
export const basePath = (p: string) => { const b = p.replace(/^\/(nl|fr)(?=\/|$)/, '') || '/'; return /^\/404/.test(b) ? '/' : b; };
export const langOf = (p: string): Lang => (/^\/nl(\/|$)/.test(p) ? 'nl' : /^\/fr(\/|$)/.test(p) ? 'fr' : 'en');
